double lhs( double x, double y){ return sin(x*m)*sin(y*n);}

double GyroLagK(int n, double x) { return pow(-x,n)/tgamma(n+1)*exp(x);}

double psi_Ogata(double x) { return x*tanh(M_PI/2. * sinh(x)); }

double psis_Ogata(double x) { return M_PI/2. * x * cosh(x) * pow(cosh(M_PI/2. * sinh(x)),-2.0) + tanh(M_PI/2. * sinh(x)) ; }

double weights_Ogata(double x) { return M_PI *boost::math::cyl_neumann(0,x)/boost::math::cyl_bessel_j(1, x); }

///@brief \f$ f(x) = BesselJ(n,x)\f$
template< class T = double >
struct BesselJ
{
    BesselJ(unsigned n): m_n(n) {}

    DG_DEVICE T operator() ( T x) const
    {
        return boost::math::cyl_bessel_j(m_n, x);
    }
    private:
    	unsigned m_n;
};

///@brief \f$ f(x) = LaguerreL(n,x)\f$
template< class T = double >
struct LaguerreL
{
    LaguerreL(unsigned n): m_n(n) {}

    DG_DEVICE T operator() ( T x) const
    {
        return boost::math::laguerre(m_n, x);
    }
    private:
        unsigned m_n;
};

///@brief \f$ f(x) = x^power\f$
template< class T = double >
struct POW
{
    POW(double power): m_power(power) {}
    DG_DEVICE T operator() (T x) const
    {
	    return pow(x, m_power);
    }
	private:
        double m_power;
};

///@brief \f$ f(x) = exp(-x)*LaguerreL(n,x)*BesselJ(0,Sqrt(4.0*x*t))\f$
template<class T = double>
struct Gyrointegrant
{
    Gyrointegrant(double t, unsigned n):m_t(t), m_n(n) {}

    DG_DEVICE T  operator()(double x) const
    {
        return exp(-x)*boost::math::laguerre(m_n, x)*boost::math::cyl_bessel_j(0, sqrt(4.0*x*m_t));
    }
  private:
    double  m_t;
    unsigned m_n;
};

///@brief \f$ f(x) =x/2* exp(-x^2/4)*LaguerreL(n,x^2/4)*BesselJ(0,x*Sqrt(t))\f$
template<class T = double>
struct Gyrointegranttrans
{
    Gyrointegranttrans(double t, unsigned n):m_t(t), m_n(n) {}

    DG_DEVICE T  operator()(double x) const
    {
        return x/2.0*exp(-x*x/4.)*boost::math::laguerre(m_n, x*x/4.)*boost::math::cyl_bessel_j(0, x*sqrt(m_t));
    }
  private:
    double m_t;
    unsigned m_n;
};

///@brief \f$ f(x) =x/(2*t) exp(-x^2/(4*t))*LaguerreL(n,x^2/(4*t))*BesselJ(0,x)\f$
template<class T = double>
struct Gyrointegranttrans2
{
    Gyrointegranttrans2(double t, unsigned n):m_t(t), m_n(n) {}

    DG_DEVICE T  operator()(double x) const
    {
        return x/(2.0*m_t)*exp(-x*x/(4.*m_t))*boost::math::laguerre(m_n, x*x/(4.*m_t))*boost::math::cyl_bessel_j(0, x);
    }
  private:
    double m_t;
    unsigned m_n;
};


using Matrix = dg::DMatrix;
